import React,{useEffect,useState}from'react';
import {supabase as sb} from '../lib/supabase.js';
const cats=['Venue','Catering','Photography','Videography','Decoration','Makeup and beauty','Mehendi','DJ and entertainment','Wedding planning','Transportation','Invitation design','Lighting','Other'];
const paths=['dashboard','shop','services','enquiries','bookings','negotiations','earnings','settings'];
const go=p=>{history.pushState({},'',p);dispatchEvent(new PopStateEvent('popstate'))};
const Brand=()=> <a className="vp-brand" href="/">p.<b>pact<span>ai</span></b><small>VENDOR PORTAL</small></a>;
const Missing=()=> <div className="vp-notice"><b>Vendor backend not configured.</b><p>Add <code>VITE_SUPABASE_URL</code> and <code>VITE_SUPABASE_ANON_KEY</code> in Render, then run <code>supabase/vendor_portal.sql</code>. No account data is stored in this browser as a substitute.</p></div>;
function Auth({kind}){const[form,set]=useState({});const[msg,setMsg]=useState('');const change=e=>set({...form,[e.target.name]:e.target.value});const submit=async e=>{e.preventDefault();if(!sb)return setMsg('This portal needs Supabase configuration before accounts can be created.');if(kind==='register'){if(!form.terms||!form.name||!form.business||!form.phone||!form.category||!form.city)return setMsg('Complete every field and accept the terms.');if(!/^\S+@\S+\.\S+$/.test(form.email||''))return setMsg('Enter a valid email address.');if(!/^\+?[0-9 ()-]{7,20}$/.test(form.phone))return setMsg('Enter a valid phone number.');if((form.password||'').length<8)return setMsg('Use a password of at least 8 characters.');if(form.password!==form.confirm)return setMsg('Passwords do not match.');const{data,error}=await sb.auth.signUp({email:form.email,password:form.password,options:{data:{full_name:form.name,business_name:form.business,phone:form.phone,category:form.category,city:form.city,role:'vendor'},emailRedirectTo:location.origin+'/vendor/onboarding'}});if(error)return setMsg(error.message);setMsg('Check your inbox to confirm your account, then sign in.');return}if(kind==='forgot'){const{error}=await sb.auth.resetPasswordForEmail(form.email,{redirectTo:location.origin+'/vendor/settings'});return setMsg(error?error.message:'Password-reset email sent if this address is registered.')}const{error}=await sb.auth.signInWithPassword({email:form.email,password:form.password});if(error)return setMsg('Unable to sign in. Check your email and password.');go('/vendor/dashboard')};const isReg=kind==='register';return <main className="vp-auth"><Brand/><section className="vp-card"><p className="vp-kicker">{isReg?'JOIN PACTAI':'VENDOR ACCESS'}</p><h1>{isReg?'Create your vendor account':kind==='forgot'?'Reset your password':'Welcome back.'}</h1><p>{isReg?'Start your business profile, then finish your shop when you are ready.':'Secure access for PactAI event professionals.'}</p><form onSubmit={submit}>{isReg&&<><input name="name" placeholder="Full name" onChange={change}/><input name="business" placeholder="Business / shop name" onChange={change}/></>}<input required name="email" type="email" placeholder="Email address" onChange={change}/>{isReg&&<><input name="phone" placeholder="Phone number" onChange={change}/><select name="category" defaultValue="" onChange={change}><option value="" disabled>Business category</option>{cats.map(x=><option key={x}>{x}</option>)}</select><input name="city" placeholder="City" onChange={change}/></>}{kind!=='forgot'&&<><input required name="password" type="password" minLength="8" placeholder="Password" onChange={change}/>{isReg&&<input name="confirm" type="password" placeholder="Confirm password" onChange={change}/>}</>}{isReg&&<label className="vp-check"><input name="terms" type="checkbox" onChange={e=>set({...form,terms:e.target.checked})}/> I accept PactAI’s Terms and Conditions.</label>}<button className="vp-primary">{isReg?'Create vendor account':kind==='forgot'?'Send reset link':'Sign in'}</button></form>{msg&&<p className="vp-message">{msg}</p>}<p className="vp-switch">{isReg?'Already registered? ':kind==='forgot'?'Remembered it? ':'New to PactAI? '}<a href={isReg?'/vendor/login':kind==='forgot'?'/vendor/login':'/vendor/register'}>{isReg?'Sign in':kind==='forgot'?'Sign in':'Register as a Vendor'}</a></p></section></main>}
function Welcome(){return <main className="vp-welcome"><Brand/><div className="vp-hero"><section><p className="vp-kicker">PACTAI FOR VENDORS</p><h1>Your business deserves a better stage.</h1><p>Join PactAI's growing network of event professionals. Showcase your services, connect with customers, manage bookings, and grow your business.</p><div><a className="vp-primary" href="/vendor/register">Register as a Vendor</a><a className="vp-secondary" href="/vendor/login">Sign In</a></div></section><div className="vp-photo"><span>PHOTOGRAPHERS · DECORATORS · CATERERS · VENUES</span></div></div><section className="vp-benefits">{['Showcase your business','List and manage services','Receive customer enquiries','Negotiate with customers','Manage bookings','Track business activity'].map((x,i)=><article key={x}><b>0{i+1}</b><h3>{x}</h3></article>)}</section></main>}
function Shell({user}){const[profile,setProfile]=useState(null);const[services,setServices]=useState([]);const[enquiries,setEnquiries]=useState([]);const[bookings,setBookings]=useState([]);const[path,setPath]=useState(location.pathname.split('/').pop());const[notice,setNotice]=useState('');const refresh=async()=>{let{data:p}=await sb.from('vendor_profiles').select('*').eq('id',user.id).single();let{data:s}=await sb.from('vendor_services').select('*').eq('vendor_id',user.id).order('created_at',{ascending:false});let{data:e}=await sb.from('enquiries').select('*').eq('vendor_id',user.id).order('created_at',{ascending:false});let{data:b}=await sb.from('bookings').select('*').eq('vendor_id',user.id).order('created_at',{ascending:false});setProfile(p);setServices(s||[]);setEnquiries(e||[]);setBookings(b||[]) };useEffect(()=>{refresh()},[]);useEffect(()=>{const f=()=>setPath(location.pathname.split('/').pop());addEventListener('popstate',f);return()=>removeEventListener('popstate',f)},[]);const save=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const{error}=await sb.from('vendor_profiles').upsert({...profile,...d,id:user.id,updated_at:new Date().toISOString()});setNotice(error?error.message:'Saved.');refresh()};const addService=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const price=Number(d.price);const minimumPrice=Number(d.minimum_price);if(!Number.isFinite(price)||!Number.isFinite(minimumPrice)||minimumPrice<0||minimumPrice>price){setNotice('Minimum acceptable price must be between zero and the listed price.');return}const{error}=await sb.from('vendor_services').insert({vendor_id:user.id,name:d.name,category:d.category,description:d.description,price,minimum_price:minimumPrice,is_published:d.is_published==='on'});setNotice(error?error.message:'Service added. Your minimum price is kept private from customers.');if(!error)e.target.reset();refresh()};const updateMinimumPrice=async(e,service)=>{e.preventDefault();const value=Number(new FormData(e.target).get('minimum_price'));if(!Number.isFinite(value)||value<0||value>Number(service.price)){setNotice('Minimum acceptable price must be between zero and the listed price.');return}const{error}=await sb.from('vendor_services').update({minimum_price:value}).eq('id',service.id).eq('vendor_id',user.id);setNotice(error?error.message:'Private minimum price updated.');if(!error)refresh()};const del=async id=>{await sb.from('vendor_services').delete().eq('id',id);refresh()};const nav=x=><a className={path===x?'active':''} href={'/vendor/'+x}>{x[0].toUpperCase()+x.slice(1)}</a>;let body;if(path==='dashboard')body=<><h1>Good to see you, {profile?.full_name?.split(' ')[0]||'Vendor'}.</h1><div className="vp-stats"><b>{profile?.business_name||'Your shop'}<small>MY SHOP</small></b><b>{services.length}<small>MY SERVICES</small></b><b>{enquiries.filter(x=>x.status==='new').length}<small>NEW ENQUIRIES</small></b><b>{bookings.filter(x=>x.status==='confirmed'||x.status==='requested').length}<small>ACTIVE BOOKINGS</small></b><b>₹0<small>MONTHLY EARNINGS</small></b></div><p className="vp-muted">Complete your shop profile and publish a service to appear in the PactAI marketplace after the backend is configured.</p></>;else if(path==='shop'||path==='onboarding'||path==='settings')body=<><h1>{path==='onboarding'?'Set up your shop':path==='settings'?'Account settings':'My shop'}</h1><form className="vp-form" onSubmit={save}>{[['business_name','Business name'],['description','Business description'],['address','Business address'],['city','City'],['service_locations','Service locations'],['years_experience','Years of experience'],['phone','Contact phone'],['instagram_url','Instagram URL'],['website_url','Website URL']].map(([n,l])=><label key={n}>{l}<input name={n} defaultValue={profile?.[n]||''}/></label>)}<label className="vp-check"><input name="is_published" type="checkbox" defaultChecked={profile?.is_published}/> Publish my shop</label><button className="vp-primary">Save changes</button></form></>;else if(path==='services')body=<><h1>My services</h1><form className="vp-form vp-service-form" onSubmit={addService}><input name="name" required placeholder="Service name"/><select name="category">{cats.map(x=><option key={x}>{x}</option>)}</select><input name="price" required type="number" min="0" placeholder="Listed starting price"/><input name="minimum_price" required type="number" min="0" placeholder="Minimum acceptable price (private)"/><input name="description" placeholder="Description"/><label className="vp-check"><input name="is_published" type="checkbox"/> Publish in marketplace</label><button className="vp-primary">Add service</button></form><div className="vp-list">{services.map(s=><article key={s.id}><b>{s.name}</b><span>{s.category} · ₹{s.price} · Private minimum ₹{s.minimum_price} · {s.is_published?'Published':'Draft'}</span><form className="vp-floor-edit" onSubmit={e=>updateMinimumPrice(e,s)}><label>Update private minimum<input name="minimum_price" required type="number" min="0" max={s.price} defaultValue={s.minimum_price??s.price}/></label><button className="vp-primary">Save minimum</button></form><button onClick={()=>del(s.id)}>Delete</button></article>)}</div></>;else if(path==='enquiries')body=<><h1>Customer enquiries</h1>{!enquiries.length?<div className="vp-empty">No enquiries yet. When a customer sends a request from the PactAI event planner, it will appear here.</div>:<div className="vp-list">{enquiries.map(x=><article key={x.id}><div><b>{x.event_date||'Date to be confirmed'} · {x.status}</b><span>{x.message}</span>{x.proposed_price!=null&&<b>Customer opening proposal: ₹{Number(x.proposed_price).toLocaleString('en-IN')}</b>}<small>Request {x.id.slice(0,8)} · {new Date(x.created_at).toLocaleString()}</small></div></article>)}</div>}</>;else if(path==='bookings')body=<><h1>Bookings</h1>{!bookings.length?<div className="vp-empty">No bookings have been created yet. Customer enquiries are shown in the Enquiries section until both sides agree to a booking.</div>:<div className="vp-list">{bookings.map(x=><article key={x.id}><div><b>{x.event_date} · {x.status}</b><span>Agreed price ₹{Number(x.agreed_price).toLocaleString('en-IN')}</span><small>Booking {x.id.slice(0,8)}</small></div></article>)}</div>}</>;else body=<><h1>{path[0].toUpperCase()+path.slice(1)}</h1><div className="vp-empty">This section is not connected yet. Customer enquiries and bookings are available in their respective sections.</div></>;return <main className="vp-shell"><aside><Brand/>{paths.map(nav)}<button onClick={()=>sb.auth.signOut().then(()=>go('/vendor/login'))}>Log out</button></aside><section className="vp-content">{notice&&<p className="vp-message">{notice}</p>}{body}</section></main>}
export default function VendorPortal(){const[path,setPath]=useState(location.pathname);const[user,setUser]=useState(null);useEffect(()=>{const f=()=>setPath(location.pathname);addEventListener('popstate',f);if(sb){sb.auth.getUser().then(({data})=>setUser(data.user));const{data:{subscription}}=sb.auth.onAuthStateChange((_e,s)=>setUser(s?.user||null));return()=>{removeEventListener('popstate',f);subscription.unsubscribe()}}return()=>removeEventListener('popstate',f)},[]);if(path==='/vendor')return <Welcome/>;if(['register','login','forgot-password'].includes(path.split('/').pop()))return <Auth kind={path.endsWith('register')?'register':path.endsWith('forgot-password')?'forgot':'login'}/>;if(!sb)return <><Welcome/><Missing/></>;if(!user){go('/vendor/login');return null}return <Shell user={user}/>};
export function VendorEntry(){return <a className="vendor-entry" href="/vendor">For Vendors</a>};